import{_ as a,o as s,c as n,a2 as o,j as t,a as d,t as c}from"./chunks/framework.CZqXuAiL.js";const b=JSON.parse('{"title":"Configuration Reference — Glacier Pack","description":"Every setting on every Glacier Pack addon pane — name, type, default, what it does, when to change it, and common mistakes — grouped per addon.","frontmatter":{"title":"Configuration Reference — Glacier Pack","description":"Every setting on every Glacier Pack addon pane — name, type, default, what it does, when to change it, and common mistakes — grouped per addon.","outline":"deep"},"headers":[],"relativePath":"glacier-pack/configuration/reference.md","filePath":"glacier-pack/configuration/reference.md","lastUpdated":1786493560000}'),i={name:"glacier-pack/configuration/reference.md"};function l(r,e,h,p,g,u){return s(),n("div",null,[e[7]||(e[7]=o('<h1 id="configuration-reference" tabindex="-1">Configuration Reference <a class="header-anchor" href="#configuration-reference" aria-label="Permalink to &quot;Configuration Reference&quot;">​</a></h1><p>Every setting that actually exists on the 46 Glacier Pack addon panes, grouped per addon with an anchor each. Settings marked <strong>(env-only)</strong> live in the addon&#39;s config file and are tuned via <code>.env</code>, not the hub. Addons that manage <em>records</em> instead of settings (rules, destinations, alerts) list those fields under <strong>Managed data</strong>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>All saves go through the hub&#39;s <code>_hub</code> round-trip: you always land back on the same pane, with validation errors shown above the form when a value is rejected.</p></div><h2 id="egg-name-gating-shared-by-all-game-addons" tabindex="-1">Egg-name gating (shared by all game addons) <a class="header-anchor" href="#egg-name-gating-shared-by-all-game-addons" aria-label="Permalink to &quot;Egg-name gating (shared by all game addons)&quot;">​</a></h2><p>Every game-specific addon ships with a default <strong>egg-name gate</strong>: it only appears on servers whose egg name matches its shipped pattern (ARK tools on ARK eggs, Hytale on Hytale, FiveM on FiveM, FastDL on Source-engine games, Bedrock addons on Bedrock eggs, the Minecraft Java tools on Java eggs). Two settings control this on each addon&#39;s pane:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>egg_name_gating</code></td><td>checkbox</td><td>on</td><td>Master switch for name-based gating. Off = the addon shows on every egg.</td></tr><tr><td><code>egg_name_pattern</code></td><td>text (regex)</td><td>per-addon pattern</td><td>Case-insensitive regex matched against the server&#39;s egg <strong>name</strong> (IDs differ per install, names don&#39;t). A live hint under the field shows how many of the panel&#39;s eggs match as you type.</td></tr></tbody></table><p>Addons that already had an egg-ID allowlist keep it — an ID match always wins, even when the name pattern doesn&#39;t. Server Wiper is the exception to the family rule: the wiper itself is universal and only its Rust map library gates to Rust eggs.</p><hr><h2 id="basic-pack" tabindex="-1">Basic pack <a class="header-anchor" href="#basic-pack" aria-label="Permalink to &quot;Basic pack&quot;">​</a></h2><h3 id="audit-log" tabindex="-1">Audit Log <a class="header-anchor" href="#audit-log" aria-label="Permalink to &quot;Audit Log {#audit-log}&quot;">​</a></h3><p>No settings form — the pane is a filterable viewer (full-text search, event scope, actor type, date range) with a per-entry detail dialog and retention tools (prune entries older than N days, or clear the log; both behind confirmation prompts).</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>per_page</code> <strong>(env-only)</strong></td><td>number</td><td><code>25</code> (<code>AUDIT_LOG_PER_PAGE</code>)</td><td>Entries listed per page (clamped 1–100).</td></tr></tbody></table><p><strong>Common mistakes:</strong> treating prune/clear as reversible — both delete activity rows permanently; expecting entries the panel never recorded — the addon reads the stock <code>activity_logs</code> feed and adds no extra logging of its own.</p><hr><h3 id="auto-suspend" tabindex="-1">Auto Suspend <a class="header-anchor" href="#auto-suspend" aria-label="Permalink to &quot;Auto Suspend {#auto-suspend}&quot;">​</a></h3><p>Sub-tabs: <strong>Overview</strong> (counters + latest activity), <strong>Servers</strong> (per-server expiry dates, one inline form per row), <strong>History</strong>, <strong>Settings</strong>. Settings save to <code>admin.auto-suspend.settings.update</code>.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>suspension_enabled</code></td><td>checkbox</td><td>on</td><td>Master switch — off pauses warnings, suspensions, lifts and deletions.</td></tr><tr><td><code>warn_days</code></td><td>number (0–60)</td><td><code>3</code></td><td>Days before expiry the owner receives one warning email; <code>0</code> disables it.</td></tr><tr><td><code>auto_delete_enabled</code></td><td>checkbox</td><td>off</td><td>Delete servers suspended by this addon once they outstay the grace period.</td></tr><tr><td><code>auto_delete_days</code></td><td>number (1–365)</td><td><code>14</code></td><td>Grace period in days (suspended) before auto-delete fires.</td></tr><tr><td><code>excluded_nodes[]</code></td><td>multi-select</td><td>empty</td><td>Nodes whose servers are never auto-deleted.</td></tr><tr><td><code>retention_days</code></td><td>number (7–365)</td><td><code>90</code></td><td>History rows older than this are pruned daily.</td></tr></tbody></table><p><strong>Managed data:</strong> per-server expiry dates on the <strong>Servers</strong> tab. Extending a suspended server&#39;s expiry into the future lifts the suspension on the next scheduler pass.</p><p><strong>Common mistakes:</strong> missing the panel cron — processing runs every five minutes via <code>schedule:run</code> (<code>php artisan auto-suspend:process</code> by hand); warning emails silently absent when the panel&#39;s mail settings are broken; expecting manual suspensions to be auto-deleted — only addon-applied suspensions are eligible.</p><hr><h3 id="command-history" tabindex="-1">Command History <a class="header-anchor" href="#command-history" aria-label="Permalink to &quot;Command History {#command-history}&quot;">​</a></h3><p>Sub-tabs: <strong>Overview</strong> (capture status, totals, per-server counts, the 25 most recent commands panel-wide, per-server purge and purge-everything) and <strong>Settings</strong>.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>checkbox</td><td>on</td><td>Pause/resume capture panel-wide.</td></tr><tr><td><code>max_per_server</code></td><td>number (50–1000)</td><td><code>200</code></td><td>Entries kept per server; excess is pruned on save.</td></tr><tr><td><code>list_limit</code> <strong>(env-only)</strong></td><td>number</td><td><code>50</code> (<code>COMMAND_HISTORY_LIST_LIMIT</code>)</td><td>Newest entries shown in the console dropdown.</td></tr></tbody></table><p>Both UI settings also have env defaults (<code>COMMAND_HISTORY_ENABLED</code>, <code>COMMAND_HISTORY_MAX_PER_SERVER</code>).</p><p><strong>Common mistakes:</strong> expecting the dropdown to show the full retention — it always shows the newest <code>list_limit</code> entries; purges (per-server or global) have no undo.</p><hr><h3 id="config-editor" tabindex="-1">Config Editor <a class="header-anchor" href="#config-editor" aria-label="Permalink to &quot;Config Editor {#config-editor}&quot;">​</a></h3><p>No settings form — this pane edits the panel&#39;s live <code>.env</code> directly. Sub-tabs: <strong>Editor</strong> (structured, grouped by prefix) and <strong>Raw file</strong> (whole-file textarea).</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>env[&lt;KEY&gt;]</code> (per parsed key)</td><td>text / password / true-false select</td><td>current <code>.env</code> value</td><td>One input per env key. Secret-looking keys (<code>PASSWORD</code>, <code>SECRET</code>, <code>KEY</code>, <code>TOKEN</code>, <code>SALT</code>) are masked with a reveal toggle; boolean keys get dropdowns.</td></tr><tr><td><code>env[APP_KEY]</code></td><td>password</td><td>always blank</td><td>Write-only. Blank keeps the current key; pasting a new one rotates it (format-validated as Laravel <code>base64:</code> or 32-char).</td></tr><tr><td><code>contents</code> (Raw tab)</td><td>textarea</td><td>entire file verbatim</td><td>Bulk raw edit with the same validation, backup and atomic-write flow.</td></tr><tr><td><code>backups_keep</code> <strong>(env-only)</strong></td><td>number</td><td><code>10</code></td><td>Timestamped <code>.env</code> snapshots kept in <code>storage/app/config-editor/backups</code>.</td></tr></tbody></table><p><strong>Common mistakes</strong></p><ul><li><strong>Editing <code>APP_KEY</code>.</strong> Never. Panel data encrypted with it (node database passwords) becomes unreadable.</li><li><strong>Changing <code>APP_NAME</code>, <code>SESSION_*</code>, <code>CACHE_PREFIX</code> or <code>REDIS_*</code> casually</strong> — it invalidates every active session panel-wide, logging everyone out immediately.</li><li>Forgetting that backups contain full <code>.env</code> secrets — they are written <code>0640</code> in a <code>0750</code> directory; treat them like the <code>.env</code> itself.</li></ul><hr><h3 id="console-log-share" tabindex="-1">Console Log Share <a class="header-anchor" href="#console-log-share" aria-label="Permalink to &quot;Console Log Share {#console-log-share}&quot;">​</a></h3><p>Single settings pane (no sub-tabs). Posts to <code>admin.console-log-share.update</code>; <strong>Reset to Defaults</strong> restores the shipped values.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>paste_endpoint</code></td><td>url</td><td><code>https://api.mclo.gs/1/log</code></td><td>Any mclogs-compatible API: the panel POSTs the log as form field <code>content</code> and expects JSON containing <code>url</code>. Change when self-hosting a paste service.</td></tr><tr><td><code>upload_enabled</code></td><td>checkbox</td><td>on</td><td>Off hides the Share button and rejects uploads; <strong>Copy Log stays available</strong>.</td></tr><tr><td><code>placement</code></td><td>select</td><td><code>top</code> (Above the console)</td><td>Where the Copy/Share bar renders on the console page.</td></tr><tr><td><code>default_paste_endpoint</code> <strong>(env-only)</strong></td><td>—</td><td><code>CONSOLE_LOG_SHARE_PASTE_ENDPOINT</code>, same URL</td><td>Shipped default the reset button returns to.</td></tr><tr><td><code>max_log_lines</code> <strong>(env-only)</strong></td><td>number</td><td><code>1500</code> (<code>CONSOLE_LOG_SHARE_MAX_LINES</code>)</td><td>Trailing console lines requested from the node.</td></tr><tr><td><code>max_upload_bytes</code> <strong>(env-only)</strong></td><td>number</td><td><code>5242880</code> (<code>CONSOLE_LOG_SHARE_MAX_BYTES</code>)</td><td>Largest payload pushed to the paste service; older lines are trimmed beyond it.</td></tr></tbody></table><p><strong>Common mistakes:</strong> pointing <code>paste_endpoint</code> at a plain HTML pastebin (it must be the mclogs-compatible <em>API</em> URL); changing env overrides without <code>php artisan config:clear</code>.</p><hr><h3 id="login-activity" tabindex="-1">Login Activity <a class="header-anchor" href="#login-activity" aria-label="Permalink to &quot;Login Activity {#login-activity}&quot;">​</a></h3><p>No settings form. Sub-tabs: <strong>Logins</strong> (full history with user / date-range filters, pagination) and <strong>Sessions</strong> (live mirrored sessions with user filter, per-row revoke and revoke-all for one user). Deleted users show as &quot;Deleted user #id&quot;.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>admin_per_page</code> <strong>(env-only)</strong></td><td>number</td><td><code>25</code> (<code>LOGIN_ACTIVITY_ADMIN_PER_PAGE</code>)</td><td>Rows per page on the admin overview (clamped 1–100).</td></tr><tr><td><code>client_per_page</code> <strong>(env-only)</strong></td><td>number</td><td><code>8</code> (<code>LOGIN_ACTIVITY_CLIENT_PER_PAGE</code>)</td><td>Rows per page in the account-area widget.</td></tr><tr><td><code>sessions.enabled</code> <strong>(env-only)</strong></td><td>bool</td><td><code>true</code> (<code>LOGIN_ACTIVITY_SESSIONS</code>)</td><td>Mirror and track live sessions for the Sessions tab and self-service revoke.</td></tr><tr><td><code>geo.enabled</code> <strong>(env-only)</strong></td><td>bool</td><td><code>true</code> (<code>LOGIN_ACTIVITY_GEO</code>)</td><td>Coarse ipwho.is geolocation per unique IP; set <code>false</code> to keep IPs in-house.</td></tr><tr><td><code>geo.cache_days</code> <strong>(env-only)</strong></td><td>number</td><td><code>30</code> (<code>LOGIN_ACTIVITY_GEO_CACHE_DAYS</code>)</td><td>One lookup per unique IP per cache window.</td></tr><tr><td><code>proxy.detection</code> <strong>(env-only)</strong></td><td>—</td><td><code>heuristic</code> (<code>LOGIN_ACTIVITY_PROXY_DETECTION</code>)</td><td>Network-name keyword heuristic; set <code>proxycheck</code> for an authoritative verdict.</td></tr><tr><td><code>LOGIN_ACTIVITY_PROXYCHECK_KEY</code> <strong>(env-only)</strong></td><td>—</td><td>empty</td><td>Free-tier proxycheck.io key, only used with the <code>proxycheck</code> detector.</td></tr></tbody></table><p><strong>Common mistakes:</strong> expecting authoritative VPN detection out of the box — the default heuristic is best-effort (set the proxycheck mode for a real verdict); a revoked session is not instant-logout down to the millisecond — it dies on its very next request. History is kept on uninstall unless you pass <code>--drop-table</code> to <code>remove.sh</code>.</p><hr><h3 id="move-files" tabindex="-1">Move Files <a class="header-anchor" href="#move-files" aria-label="Permalink to &quot;Move Files {#move-files}&quot;">​</a></h3><p>No settings at all — the pane is an informational card. The addon enhances every server&#39;s file manager automatically once installed; there is no config file and no backend.</p><p><strong>Common mistakes:</strong> forgetting a hard refresh (<code>Ctrl+Shift+R</code>) on the Files page after install, and forgetting to re-run <code>install.sh</code> after panel updates overwrite <code>templates/base/core.blade.php</code>.</p><hr><h3 id="node-status" tabindex="-1">Node Status <a class="header-anchor" href="#node-status" aria-label="Permalink to &quot;Node Status {#node-status}&quot;">​</a></h3><p>Sub-tabs: <strong>Overview</strong> (settings + per-node overrides), <strong>Monitors</strong>, <strong>Sharing &amp; Alerts</strong>, <strong>Service Updates</strong>. Settings save to <code>admin.uptime.settings</code>.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>checkbox</td><td>on</td><td>Master switch — off hides the Uptime tab and stops collection.</td></tr><tr><td><code>poll_interval</code></td><td>select</td><td><code>60</code> s (30 / 60 / 120 / 300)</td><td>How often the panel polls Wings. Lower = fresher graphs, more node load. The collector honors the configured interval.</td></tr><tr><td><code>retention_days</code></td><td>select</td><td><code>90</code> (30–365)</td><td>Nightly pruning horizon; the graph window maxes at 365 days.</td></tr><tr><td><code>users_see_node_uptime</code></td><td>checkbox</td><td>on</td><td>Whether regular users see node health data.</td></tr><tr><td><code>show_node_names</code></td><td>checkbox</td><td>off</td><td>Off masks real node names/FQDNs for users (&quot;Your Node&quot;, &quot;Node 1&quot;); admins always see real names.</td></tr><tr><td><code>public_page_enabled</code></td><td>checkbox</td><td>off</td><td>Unauthenticated <code>/status</code> page plus JSON feed (<code>/api/uptime-public/summary</code>), rate-limited and <code>noindex</code>.</td></tr><tr><td><code>public_page_title</code></td><td>text</td><td>shipped string</td><td>Title of the public status page.</td></tr><tr><td><code>public_show_uptime</code> / <code>public_show_latency</code> / <code>public_show_monitors</code> / <code>public_show_notices</code></td><td>checkboxes</td><td>on</td><td>Per-element display toggles for the public page.</td></tr><tr><td><code>public_show_node_names</code></td><td>checkbox</td><td>off</td><td>Show real node names publicly — node FQDNs are never exposed either way.</td></tr><tr><td><code>discord_webhook_url</code></td><td>url</td><td>empty</td><td>Discord webhook for down/resolved incident embeds.</td></tr><tr><td><code>discord_alert_nodes</code> / <code>discord_alert_monitors</code></td><td>checkboxes</td><td>on</td><td>Alert categories: node and monitor transitions.</td></tr><tr><td><code>discord_alert_servers</code></td><td>checkbox</td><td>off</td><td>Also alert on per-server transitions (noisy on big panels).</td></tr><tr><td><code>discord_hide_endpoint</code></td><td>checkbox</td><td>off</td><td>Mask the endpoint in alerts posted to public channels.</td></tr><tr><td><code>job_timeout</code> / <code>node_connect_timeout</code> / <code>monitor_timeout</code> / <code>cache_ttl</code> <strong>(env-only)</strong></td><td>numbers</td><td><code>45</code> / <code>3</code> / <code>6</code> / <code>300</code></td><td>Collection job timeout, per-node and per-monitor connect timeouts, cache TTL (seconds).</td></tr></tbody></table><p><strong>Managed data:</strong> per-node tracking overrides (toggle per node); custom <strong>Monitors</strong> (<code>name</code>, <code>type</code> — <code>http</code> / <code>tcp</code> / <code>udp</code>, <code>target</code>, <code>port</code>), each with live state, 24 h uptime, latency, last check, failure reason and pause/resume; <strong>Service Update</strong> posts with <code>title</code> (required), <code>event_at</code> (optional — renders a live countdown) and <code>body_html</code> (required; whitelisted basic HTML). A <strong>Send test alert</strong> button verifies the Discord webhook.</p><p><strong>Common mistakes:</strong> missing the panel cron — collection (<code>uptime:collect</code>) and pruning run via the scheduler; forgetting the <code>uptime.read</code> subuser permission, without which users see no Uptime tab; reading UDP monitors as proof of life — a silent host counts as up unless the network refuses the packet (noted in the UI).</p><hr><h3 id="pwa" tabindex="-1">PWA <a class="header-anchor" href="#pwa" aria-label="Permalink to &quot;PWA {#pwa}&quot;">​</a></h3><p>Single settings pane (posts to <code>admin.pwa.update</code>) with live endpoint links; <strong>Reset to Defaults</strong> restores the shipped values, disables the shell and rolls client caches on the next page load.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>checkbox</td><td>off</td><td>Master switch. Disabling makes every client unregister the service worker and purge its caches on the next page load.</td></tr><tr><td><code>app_name</code></td><td>text (max 80)</td><td>empty (panel name)</td><td>Shown in the install dialog and on the home screen.</td></tr><tr><td><code>app_short_name</code></td><td>text (max 30)</td><td>empty</td><td>Used where space is tight (under the home-screen icon).</td></tr><tr><td><code>app_description</code></td><td>textarea (max 200)</td><td>empty</td><td>Shown in some install dialogs.</td></tr><tr><td><code>theme_color</code> / <code>background_color</code></td><td>color</td><td><code>#0e4688</code></td><td>Browser toolbar color / splash-screen background.</td></tr><tr><td><code>display</code></td><td>select</td><td><code>standalone</code></td><td>Display mode; <code>standalone</code> is the classic app-window mode.</td></tr><tr><td><code>orientation</code></td><td>select</td><td><code>any</code></td><td>Orientation lock.</td></tr><tr><td><code>status_bar_style</code></td><td>select</td><td><code>default</code></td><td>iOS status bar style (Apple devices only).</td></tr><tr><td><code>icon_192</code> / <code>icon_512</code> / <code>icon_maskable</code></td><td>text</td><td>panel favicons</td><td>Paths (<code>/favicons/…</code>) or full URLs; empty slots fall back to the bundled favicons.</td></tr><tr><td><code>cache_strategy</code></td><td>select</td><td><code>cache-first</code></td><td><code>cache-first</code> (fastest) or <code>network-first</code> (freshest) for static assets.</td></tr><tr><td><code>cache_max_age</code></td><td>number (1–720)</td><td><code>24</code> h</td><td>Cached entries older than this refresh from the network.</td></tr><tr><td><code>cache_assets</code></td><td>checkbox</td><td>on</td><td>Cache panel JS/CSS/fonts/images.</td></tr><tr><td><code>cache_api</code></td><td>checkbox</td><td>off</td><td>Network-first caching of <code>/api/client</code> GET responses with a cached fallback.</td></tr><tr><td><code>offline_enabled</code></td><td>checkbox</td><td>on</td><td>Branded offline fallback page at <code>/pwa/offline</code>.</td></tr><tr><td><code>offline_title</code> / <code>offline_message</code></td><td>text</td><td>shipped strings</td><td>Offline page copy.</td></tr><tr><td><code>prompt_enabled</code></td><td>checkbox</td><td>on</td><td>Dismissible install banner; dismissed banners stay hidden seven days, iOS shows <em>Share → Add to Home Screen</em> instructions.</td></tr><tr><td><code>prompt_delay</code></td><td>number (0–600)</td><td><code>30</code> s</td><td>Delay before the banner appears.</td></tr><tr><td><code>prompt_button</code> / <code>prompt_title</code> / <code>prompt_text</code></td><td>text</td><td>shipped strings</td><td>Banner copy.</td></tr></tbody></table><p><strong>Common mistakes:</strong> testing over plain HTTP — service workers and install prompts require a secure context (localhost is exempt); enabling <code>cache_api</code> and being surprised by briefly stale data on flaky connections.</p><hr><h3 id="panel-logs" tabindex="-1">Panel Logs <a class="header-anchor" href="#panel-logs" aria-label="Permalink to &quot;Panel Logs {#panel-logs}&quot;">​</a></h3><p>No settings form — a tool pane with log files grouped by source and a tail viewer (level filters, 2/5/10/30 s auto-refresh, download, clear, delete). The panel&#39;s <code>storage/logs</code> is joined by auto-detected Nginx (<code>/var/log/nginx</code>) and Wings (<code>/var/log/pterodactyl</code>) sources plus any you configure.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>PANEL_LOGS_TAIL_LINES</code> <strong>(env-only)</strong></td><td>number</td><td><code>400</code></td><td>Lines of context loaded when a log opens.</td></tr><tr><td><code>PANEL_LOGS_SCAN_BYTES</code> <strong>(env-only)</strong></td><td>number</td><td><code>4194304</code> (4 MiB)</td><td>Backwards scan budget for the initial tail.</td></tr><tr><td><code>PANEL_LOGS_POLL_MAX_BYTES</code> <strong>(env-only)</strong></td><td>number</td><td><code>524288</code> (512 KiB)</td><td>Max bytes per poll response.</td></tr><tr><td><code>PANEL_LOGS_POLL_INTERVAL</code> <strong>(env-only)</strong></td><td>number</td><td><code>5</code> (seconds)</td><td>Default auto-refresh interval in the viewer.</td></tr></tbody></table><p><strong>Log sources (<code>config/panellogs.php</code> → <code>sources</code>):</strong> each source takes <code>label</code> (display name), <code>path</code> (absolute directory), <code>pattern</code> (glob, default <code>*.log</code>), <code>parser</code> (<code>laravel</code>, <code>auto</code> = Laravel + Nginx error + Wings, or <code>plain</code>), <code>readonly</code> (default <code>true</code> — hides and refuses clear/delete server-side) and <code>auto</code> (default <code>false</code> — silently skip when the directory is missing). Run <code>php artisan config:clear</code> after editing.</p><p><strong>Common mistakes:</strong> expecting clear/delete on external sources — they are read-only by design so the addon can never truncate web server or daemon logs; a source whose directory exists but is unreadable by the panel user shows a permission notice — grant read access (e.g. group membership) to list it.</p><hr><h3 id="quick-file-access" tabindex="-1">Quick Files <a class="header-anchor" href="#quick-file-access" aria-label="Permalink to &quot;Quick Files {#quick-file-access}&quot;">​</a></h3><p>Single pane: settings, usage stats (total pins, servers with pins, most pinned servers) plus two separate actions — <strong>Reset to defaults</strong> and <strong>Clear every pin panel-wide</strong>.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>checkbox</td><td>on</td><td>Off hides the Quick Access bar and row stars panel-wide.</td></tr><tr><td><code>max_pins</code></td><td>number (0–500)</td><td><code>25</code></td><td>Pins per server; <code>0</code> = unlimited.</td></tr></tbody></table><p><strong>Common mistakes:</strong> forgetting pins are server-wide — everyone with file access sees the same bar; worrying about the re-check button — it only drops pins whose target is confirmed missing, unlistable directories are left untouched.</p><hr><h3 id="recycle-bin" tabindex="-1">Recycle Bin <a class="header-anchor" href="#recycle-bin" aria-label="Permalink to &quot;Recycle Bin {#recycle-bin}&quot;">​</a></h3><p>Single pane: global settings, storage overview, top-servers table and per-egg overrides.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>checkbox</td><td>on</td><td>Off makes deletes permanent again (stock behavior).</td></tr><tr><td><code>retention_hours</code></td><td>number (1–8760)</td><td><code>24</code></td><td>Hours a trashed file stays recoverable before purge.</td></tr><tr><td><code>default_max_mb_per_server</code></td><td>number (0–10485760)</td><td><code>0</code> (unlimited)</td><td>Per-server trash capacity in MB, counted against the server&#39;s real disk. Set this on shared nodes. Files too large for the bin can only be deleted permanently.</td></tr><tr><td><code>max_files_per_delete</code></td><td>number (1–10000)</td><td><code>100</code></td><td>Cap per delete request.</td></tr><tr><td><code>purge_batch_size</code></td><td>number (50–5000)</td><td><code>200</code></td><td>Rows per chunk processed by the hourly purge job.</td></tr><tr><td><code>logging_enabled</code></td><td>checkbox</td><td>on</td><td>Write activity-log entries for trash / restore / purge.</td></tr><tr><td><code>protect_trash_dir</code></td><td>checkbox</td><td>on</td><td>Protects <code>.trash</code> from manual moves and deletion.</td></tr><tr><td><code>reroute_permanent_delete</code></td><td>checkbox</td><td>off</td><td>Route &quot;delete permanently&quot; requests (UI or API clients sending the <code>permanent</code> flag) through the bin too; purges from inside the bin still destroy files.</td></tr></tbody></table><p><strong>Managed data:</strong> per-egg overrides — <code>egg_id</code> (required), <code>retention_hours</code> (blank inherits global), <code>max_mb</code> (blank inherits global).</p><p><strong>Common mistakes:</strong> leaving capacity unlimited on busy nodes (trash eats real disk); not re-running <code>install.sh</code> after panel updates overwrite the patched core files. The client UI integrates at runtime, so no <code>yarn build</code> is needed (a compiled SPA integration remains optional).</p><hr><h3 id="resource-alerts" tabindex="-1">Resource Alerts <a class="header-anchor" href="#resource-alerts" aria-label="Permalink to &quot;Resource Alerts {#resource-alerts}&quot;">​</a></h3><p>Sub-tabs: <strong>Overview</strong>, <strong>Rules</strong>, <strong>History</strong>, <strong>Settings</strong>. Settings save to <code>admin.resource-alerts.settings.update</code>; <strong>Send Test Alert</strong> emails all admins and hits the configured webhooks.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>monitoring_enabled</code></td><td>checkbox</td><td>on</td><td>Pause switch — off skips every poll and fires nothing.</td></tr><tr><td><code>discord_webhook_url</code></td><td>url</td><td>empty</td><td>Discord incoming webhook for alert delivery.</td></tr><tr><td><code>slack_webhook_url</code></td><td>url</td><td>empty</td><td>Slack incoming webhook.</td></tr><tr><td><code>retention_days</code></td><td>number (1–365)</td><td><code>30</code></td><td>History records older than this are pruned daily.</td></tr><tr><td><code>history_per_page</code> <strong>(env-only)</strong></td><td>number</td><td><code>25</code></td><td>History pagination size.</td></tr></tbody></table><p><strong>Managed data (rules):</strong> <code>name</code> (max 64), <code>metric</code> (<code>cpu</code>, <code>memory</code>, <code>disk</code>, <code>network_rx</code>, <code>network_tx</code>), <code>operator</code> (<code>above</code>/<code>below</code>), <code>threshold</code> (default <code>90</code>; % for cpu/memory/disk, Mbps for network), <code>scope</code> (<code>global</code>/<code>node</code>/<code>server</code>), <code>node_id</code>/<code>server_id</code> (per scope), <code>duration_minutes</code> (1–60, default <code>1</code> — consecutive 1-minute samples outside the threshold before firing), <code>enabled</code>, <code>notify_mail</code>, <code>notify_webhook</code>. Layering: global rule → per-node override → per-server override; most specific wins.</p><p><strong>Common mistakes:</strong> enabling <code>notify_webhook</code> on rules before saving webhook URLs; treating CPU/memory/disk thresholds as absolute values (they are percentages of the server&#39;s limits); missing the panel cron — sampling runs once per minute via the scheduler.</p><hr><h3 id="schedule-presets" tabindex="-1">Schedule Presets <a class="header-anchor" href="#schedule-presets" aria-label="Permalink to &quot;Schedule Presets {#schedule-presets}&quot;">​</a></h3><p>Preset CRUD plus a global export switch on one pane.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>export_enabled</code></td><td>checkbox</td><td>on</td><td>Allow user-side JSON export/import of schedules.</td></tr><tr><td><code>max_preset_tasks</code> <strong>(env-only)</strong></td><td>number</td><td><code>10</code> (<code>SCHEDULE_PRESETS_MAX_TASKS</code>)</td><td>Task cap per preset.</td></tr><tr><td><code>max_import_bytes</code> <strong>(env-only)</strong></td><td>number</td><td><code>16384</code> (<code>SCHEDULE_PRESETS_MAX_IMPORT_BYTES</code>)</td><td>Largest accepted JSON import document.</td></tr></tbody></table><p><strong>Managed data (presets):</strong> <code>name</code>, five cron fields (with a quick-pick for common timings, validated server-side), an <em>offer to users</em> toggle, an <em>only run when online</em> flag, and an ordered task list — each task is a stock task type (send command, send power action, create backup with ignored-files payload) with a time offset (0–900 s) and a continue-on-failure flag.</p><p><strong>Common mistakes:</strong> backup tasks are refused when the server&#39;s backup limit is 0, and applies honor the panel&#39;s per-schedule task limit — both surface as clear errors to the user.</p><hr><h3 id="server-time-changer" tabindex="-1">Server Timezone <a class="header-anchor" href="#server-time-changer" aria-label="Permalink to &quot;Server Timezone {#server-time-changer}&quot;">​</a></h3><p>Single pane: master switch, label, default zone, and every server override with a per-row reset.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>checkbox</td><td>on</td><td>Off hides the client tab panel-wide.</td></tr><tr><td><code>nav_label</code></td><td>text</td><td><code>Timezone</code></td><td>Label of the tab in the server navigation.</td></tr><tr><td><code>default_timezone</code></td><td>select</td><td><code>UTC</code></td><td>Zone used by every server without an override.</td></tr></tbody></table><p>All three also have env defaults (<code>SERVERTIMECHANGER_ENABLED</code>, <code>SERVERTIMECHANGER_NAV_LABEL</code>, <code>SERVERTIMECHANGER_DEFAULT_TIMEZONE</code>).</p><p><strong>Common mistakes:</strong> expecting a running container to pick up the zone — Docker environment changes only at the next container (re)creation, so restart after changing; container images without <code>tzdata</code> fall back to UTC-style behavior (every standard yolk ships it).</p><hr><h3 id="server-wiper" tabindex="-1">Server Wiper <a class="header-anchor" href="#server-wiper" aria-label="Permalink to &quot;Server Wiper {#server-wiper}&quot;">​</a></h3><p>Sub-tabs: <strong>Overview</strong>, <strong>Executions</strong>, <strong>Settings</strong>.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>nav_label</code></td><td>text</td><td><code>Wiper</code></td><td>Client tab label.</td></tr><tr><td><code>default_timezone</code></td><td>select</td><td><code>UTC</code></td><td>Preselected zone for new schedules.</td></tr><tr><td><code>max_schedules_per_server</code></td><td>number</td><td><code>10</code></td><td>Schedule cap per server.</td></tr><tr><td><code>allow_live_wipes</code></td><td>checkbox</td><td>on</td><td>Permit wipes without stopping the server first.</td></tr><tr><td><code>retention_days</code></td><td>number</td><td><code>30</code></td><td>Execution history kept.</td></tr><tr><td><code>stop_grace_seconds</code></td><td>number</td><td><code>15</code></td><td>How long to wait for the server to go offline before wiping.</td></tr><tr><td><code>rust_eggs</code> / <code>ark_eggs</code></td><td>text</td><td>empty</td><td>Comma-separated egg IDs that unlock the Rust/ARK options.</td></tr><tr><td><code>rust_map_sizes</code></td><td>text</td><td><code>1000,1500,…,6000</code></td><td>Selectable map sizes.</td></tr><tr><td><code>rust_default_map_size</code></td><td>number</td><td><code>4500</code></td><td>Preselected map size.</td></tr></tbody></table><p><strong>Managed data:</strong> per-server wipe schedules and map libraries (up to 50 <code>.map</code> URLs) live on the client side; the <strong>Executions</strong> tab lists every run with status, files deleted, power actions, commands sent and applied Rust variables.</p><p><strong>Common mistakes:</strong> a glob that matches a folder removes the folder whole — test patterns on a throwaway server first; each schedule runs in its own timezone, not the panel&#39;s.</p><hr><h3 id="startup-presets" tabindex="-1">Startup Presets <a class="header-anchor" href="#startup-presets" aria-label="Permalink to &quot;Startup Presets {#startup-presets}&quot;">​</a></h3><p>Sub-tabs: <strong>Presets</strong> (CRUD with scope badges) and <strong>Settings</strong>.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>custom_command_enabled</code></td><td>checkbox</td><td>off</td><td>Let users with <code>startup.update</code> type a fully custom startup command instead of only picking presets.</td></tr><tr><td><code>custom_command_nest_ids[]</code> / <code>custom_command_egg_ids[]</code></td><td>multi-selects</td><td>empty (every server)</td><td>Restrict free-form editing to specific nests and/or eggs.</td></tr></tbody></table>',101)),t("p",null,[e[0]||(e[0]=t("strong",null,"Managed data (presets):",-1)),e[1]||(e[1]=d()),e[2]||(e[2]=t("code",null,"name",-1)),e[3]||(e[3]=d(", optional ",-1)),e[4]||(e[4]=t("code",null,"description",-1)),e[5]||(e[5]=d(", the startup command (egg placeholders like ",-1)),t("code",null,c(r.SERVER_MEMORY),1),e[6]||(e[6]=d(" are substituted at server start), and nest/egg scoping (empty = offered everywhere).",-1))]),e[8]||(e[8]=o('<p><strong>Common mistakes:</strong> none major — users can always reset to the egg&#39;s original startup command from the same picker.</p><hr><h3 id="url-download" tabindex="-1">URL Download <a class="header-anchor" href="#url-download" aria-label="Permalink to &quot;URL Download {#url-download}&quot;">​</a></h3><p>Single settings pane (one form, four boxes). <strong>Reset to defaults</strong> and <strong>Clear caches</strong> (remembered URLs + activity) are separate actions.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>max_file_size_value</code> + <code>max_file_size_unit</code></td><td>number + select (MB/GB)</td><td><code>10</code> <code>GB</code></td><td>Files larger than this are rejected before download. <code>0</code> = unlimited.</td></tr><tr><td><code>allowed_url_schemes</code></td><td>text</td><td><code>http,https</code></td><td>Comma-separated scheme allow-list.</td></tr><tr><td><code>allowed_file_extensions</code></td><td>text</td><td>empty (all allowed)</td><td>Comma-separated without dots, e.g. <code>zip,gz,tar,jar</code>.</td></tr><tr><td><code>max_urls_allowed</code></td><td>number (1–100)</td><td><code>3</code></td><td>URLs per batch.</td></tr><tr><td><code>max_concurrent_downloads</code></td><td>number (1–50)</td><td><code>3</code></td><td>Queued + active downloads per user per server.</td></tr><tr><td><code>max_query</code> / <code>max_query_window</code></td><td>numbers</td><td><code>10</code> / <code>60</code></td><td>URL-validation rate limit (queries per window, seconds).</td></tr><tr><td><code>button_label</code></td><td>text (max 60)</td><td><code>Download from URL</code></td><td>File-manager toolbar button label.</td></tr><tr><td><code>show_progress</code></td><td>select</td><td><code>popup</code></td><td><code>popup</code>, <code>deck</code> (modal + floating deck), <code>deck_only</code>, <code>none</code>. The deck survives page reloads.</td></tr><tr><td><code>memory_limit</code></td><td>number (1–20)</td><td><code>20</code></td><td>Remembered URL chips per user.</td></tr><tr><td><code>allow_simultaneous_downloads</code></td><td>checkbox</td><td>on</td><td>Let users run a batch simultaneously instead of queued.</td></tr><tr><td><code>prevent_incomplete_downloads</code></td><td>checkbox</td><td>on</td><td>Post-transfer verification; empty/missing results are flagged and cleaned up.</td></tr><tr><td><code>follow_redirects</code></td><td>checkbox</td><td>on</td><td>Follow HTTP redirects when probing/downloading.</td></tr><tr><td><code>allow_unknown_size</code></td><td>checkbox</td><td>off</td><td>Accept downloads whose size the HEAD probe cannot determine — size limits cannot be enforced for these.</td></tr><tr><td><code>validate_urls_on_entry</code></td><td>checkbox</td><td>on</td><td>Validate URLs as the user types.</td></tr><tr><td><code>prevent_html_downloads</code></td><td>checkbox</td><td>off</td><td>Reject URLs that resolve to HTML pages.</td></tr><tr><td><code>max_active_history</code> / <code>max_failed_history</code> / <code>max_completed_history</code></td><td>numbers (0–1000)</td><td><code>20</code> each</td><td>History rows kept per state; <code>0</code> = unlimited.</td></tr><tr><td><code>stale_download_timeout</code></td><td>number (60–86400)</td><td><code>3600</code> s</td><td>A download with no progress this long is marked failed.</td></tr><tr><td><code>probe_timeout</code> <strong>(env-only)</strong></td><td>number</td><td><code>15</code> (<code>URL_DOWNLOAD_PROBE_TIMEOUT</code>)</td><td>Seconds per remote HEAD probe.</td></tr></tbody></table><p><strong>Common mistakes:</strong> enabling <code>allow_unknown_size</code> and expecting size limits to still apply; forgetting transfers run on the node via the native <code>files/pull</code> endpoint — a broken panel↔Wings link fails every download.</p><hr><h2 id="advanced-pack" tabindex="-1">Advanced pack <a class="header-anchor" href="#advanced-pack" aria-label="Permalink to &quot;Advanced pack&quot;">​</a></h2><h3 id="ark-mod-installer" tabindex="-1">Ark Mod Installer <a class="header-anchor" href="#ark-mod-installer" aria-label="Permalink to &quot;Ark Mod Installer {#ark-mod-installer}&quot;">​</a></h3><p>Single pane: the CurseForge API key, catalogue cache counters and a flush action.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>curseforge_api_key</code></td><td>text</td><td>empty</td><td>Unlocks the Survival Ascended catalogue browser; Survival Evolved works keyless.</td></tr><tr><td><code>max_mods</code> <strong>(env-only)</strong></td><td>number</td><td><code>100</code> (<code>ARK_MOD_INSTALLER_MAX_MODS</code>)</td><td>Mod id cap per server.</td></tr><tr><td><code>ini_path</code> <strong>(env-only)</strong></td><td>path</td><td><code>ShooterGame/Saved/Config/LinuxServer/GameUserSettings.ini</code></td><td>Where <code>ActiveMods=</code> is written for eggs without a mod variable.</td></tr><tr><td><code>http_timeout</code> / cache TTLs <strong>(env-only)</strong></td><td>seconds</td><td><code>15</code>; search <code>600</code>, details <code>86400</code>, files <code>1800</code>, icons <code>86400</code></td><td><code>ARK_MOD_INSTALLER_HTTP_TIMEOUT</code>, <code>…_SEARCH_TTL</code>, <code>…_DETAILS_TTL</code>, <code>…_FILES_TTL</code>, <code>…_ICON_TTL</code>.</td></tr></tbody></table><p><strong>Common mistakes:</strong> expecting mod files to pass through the panel — installing only edits the startup variable (or <code>GameUserSettings.ini</code>) and the game server downloads the mods itself on the next boot; ini-mode ASE servers need the node reachable from the panel (Wings file API).</p><hr><h3 id="arma-reforger" tabindex="-1">Arma Reforger Tools <a class="header-anchor" href="#arma-reforger" aria-label="Permalink to &quot;Arma Reforger Tools {#arma-reforger}&quot;">​</a></h3><p>Single pane: settings, cache statistics and a one-click cache flush.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>nav_label</code></td><td>text</td><td><code>Reforger</code></td><td>Client tab label.</td></tr><tr><td><code>config_file</code></td><td>text</td><td><code>config.json</code></td><td>Default server config file the editor opens.</td></tr><tr><td><code>addons_path</code></td><td>text</td><td><code>addons</code></td><td>Path the admin-tools integration resolves addons under.</td></tr><tr><td><code>admin_tools_base_path</code></td><td>text</td><td><code>profile/profile/Misfits_Logging</code></td><td>Base path of the in-game admin mod&#39;s JSON documents.</td></tr><tr><td><code>workshop_site</code></td><td>url</td><td><code>https://reforger.armaplatform.com</code></td><td>Public workshop site used for catalogue browsing.</td></tr><tr><td><code>workshop_build_id</code></td><td>text</td><td>auto-detected</td><td>Override for the catalogue&#39;s rotating build id (auto-detect caches 6 h and re-detects on failure).</td></tr><tr><td><code>http_timeout</code></td><td>number</td><td><code>15</code> s</td><td>Catalogue request timeout.</td></tr><tr><td><code>cache_ttl_minutes</code></td><td>number</td><td><code>360</code></td><td>Workshop catalogue cache lifetime (panel database).</td></tr><tr><td><code>config_editor_enabled</code> / <code>admin_tools_enabled</code> / <code>collections_enabled</code></td><td>checkboxes</td><td>on</td><td>Per-feature toggles.</td></tr><tr><td><code>collection_limit_per_user</code></td><td>number (1–100)</td><td><code>5</code></td><td>Saved mod-list collections per user.</td></tr><tr><td><code>webhook_username</code> / <code>webhook_avatar_url</code></td><td>text</td><td><code>Server Panel</code> / empty</td><td>Identity for per-server Discord webhooks.</td></tr><tr><td><code>max_config_bytes</code> <strong>(env-only)</strong></td><td>number</td><td><code>524288</code> (<code>ARMA_REFORGER_MAX_CONFIG_BYTES</code>)</td><td>Largest config file the editor touches.</td></tr></tbody></table><p><strong>Common mistakes:</strong> a save refused after the file changed on disk is the optimistic-concurrency guard — reload and re-apply instead of expecting a silent overwrite; the panel never downloads mod binaries — the dedicated server fetches everything listed in <code>game.mods</code> at start (upstream behavior).</p><hr><h3 id="backup-pro" tabindex="-1">Backup Pro <a class="header-anchor" href="#backup-pro" aria-label="Permalink to &quot;Backup Pro {#backup-pro}&quot;">​</a></h3><p>Sub-tabs: <strong>Overview</strong>, <strong>Destinations</strong>, <strong>Backup Rules</strong>, <strong>Backups</strong>, <strong>Archives</strong>, <strong>Activity</strong>, <strong>Settings</strong>.</p><p><strong>Settings tab</strong> (<code>admin.s3backuppro.settings.update</code>):</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>default_retention_count</code></td><td>number (0–10000)</td><td><code>0</code></td><td>Copies kept for manual offloads not attached to a rule; <code>0</code> = unlimited.</td></tr><tr><td><code>show_user_ui</code></td><td>checkbox</td><td>on</td><td>&quot;Protected by S3&quot; banner and cloud badges on the user&#39;s backup page.</td></tr><tr><td><code>download_source</code></td><td>select</td><td><code>auto</code></td><td>Default download/restore source: <code>auto</code> (local first, S3 fallback), <code>local</code>, <code>cloud</code>.</td></tr><tr><td><code>allow_user_cloud_download</code></td><td>checkbox</td><td>on</td><td>Users may download backups from S3 copies.</td></tr><tr><td><code>allow_user_cloud_restore</code></td><td>checkbox</td><td>off</td><td>Users may restore from S3 copies — overwrites server files, hence off.</td></tr><tr><td><code>auto_retention_mode</code></td><td>checkbox</td><td>off</td><td>Match S3 retention to each server&#39;s panel backup limit; ignores per-rule &quot;Keep newest N&quot;.</td></tr><tr><td><code>backup_rate_limit_count</code> / <code>backup_rate_limit_seconds</code></td><td>numbers</td><td><code>2</code> / <code>600</code></td><td>Backup creation throttle; window <code>0</code> = no throttle.</td></tr><tr><td><code>notify_webhook_url</code></td><td>text</td><td>empty</td><td>Discord-compatible webhook for notifications; blank disables.</td></tr><tr><td><code>notify_level</code></td><td>select</td><td><code>failures</code></td><td><code>none</code>, <code>failures</code> (recommended), <code>all</code>.</td></tr><tr><td><code>sync_check_interval</code></td><td>number (1–1440)</td><td><code>60</code></td><td>Minutes between sync checks.</td></tr><tr><td><code>allow_user_sync_trigger</code></td><td>checkbox</td><td>off</td><td>Makes the red &quot;pending&quot; cloud icon clickable for users.</td></tr></tbody></table><p><strong>Managed data:</strong></p><ul><li><strong>Destinations</strong> — <code>name</code>, <code>access_key_id</code>, <code>secret_access_key</code> (encrypted at rest; blank on edit keeps it), <code>provider_hint</code> (<code>custom</code>/<code>aws</code>/<code>r2</code>/<code>b2</code>/<code>wasabi</code>/<code>minio</code>/<code>datalix</code> — auto-fills defaults, does not affect functionality), <code>bucket</code>, <code>region</code> (default <code>us-east-1</code>; R2 = <code>auto</code>), <code>endpoint</code> (blank = AWS), <code>prefix</code>, <code>use_path_style</code> (on; most non-AWS providers require it), <code>is_enabled</code>. One-click connection tests, per-row or &quot;test all&quot;.</li><li><strong>Backup rules</strong> — <code>name</code>, <code>target_type</code> (<code>all</code>/<code>node</code>/<code>servers</code>), <code>node_id</code> or <code>servers[]</code>, <code>destinations[]</code>, <code>backup_mode</code> (<code>mirror</code> / <code>schedule</code> / <code>both</code> / <code>off</code>), <code>interval_minutes</code> (default <code>1440</code>), <code>retention_count</code> (default <code>5</code>, <code>0</code> = unlimited), <code>retention_days</code> (<code>0</code> = no age limit), <code>offload</code> (delete node copy after upload), <code>lock_backups</code>, <code>ignored_files</code> (one glob per line, <code>.pteroignore</code> syntax).</li></ul><p><strong>Env-only tuning (<code>config/s3backuppro.php</code>):</strong> <code>S3BACKUPPRO_QUEUE_CONNECTION</code> / <code>S3BACKUPPRO_QUEUE_NAME</code> (default <code>standard</code>), multipart threshold/part size (16 MiB), <code>completion_timeout_seconds</code> (3600), <code>stale_after_minutes</code> (180), <code>max_servers_per_run</code> (100), <code>prune_time</code> (04:00), <code>log_retention_days</code> (60).</p><p><strong>Common mistakes:</strong> uploads sitting pending with a red cloud icon — almost always a missing queue worker on the <code>standard</code> queue; wrong path-style/endpoint combo for the provider (AWS: blank endpoint, path-style <strong>off</strong>; R2/B2/Wasabi/MinIO: provider endpoint, path-style <strong>on</strong>).</p><hr><h3 id="bedrock-addon-installer" tabindex="-1">Bedrock Addon Installer <a class="header-anchor" href="#bedrock-addon-installer" aria-label="Permalink to &quot;Bedrock Addon Installer {#bedrock-addon-installer}&quot;">​</a></h3><p>Single pane: settings plus the panel-wide install records with a clear action.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>checkbox</td><td>on</td><td>Off hides the client tab panel-wide.</td></tr><tr><td><code>curseforge_api_key</code></td><td>text</td><td>empty</td><td>Required — the browser stays hidden from users until a key is saved; the key never leaves the panel.</td></tr><tr><td><code>allowed_types[]</code></td><td>checkboxes</td><td>all four</td><td>Catalogue sections users may browse: addons, resource packs, scripts, world templates.</td></tr><tr><td><code>default_type</code></td><td>select</td><td><code>addons</code></td><td>Preselected section.</td></tr><tr><td><code>egg_ids</code></td><td>text</td><td>empty (every egg)</td><td>Restrict the browser to specific egg IDs.</td></tr><tr><td><code>cache_ttl</code></td><td>number</td><td><code>300</code> s</td><td>Catalogue cache lifetime.</td></tr></tbody></table><p><strong>Common mistakes:</strong> behavior/resource packs activate in the world named by <code>level-name</code> (default <code>world</code>) — point it elsewhere first if you run multiple worlds; a restart is usually required before new packs take effect; record cleanup never touches pack files on servers.</p><hr><h3 id="bedrock-version-changer" tabindex="-1">Bedrock Version Changer <a class="header-anchor" href="#bedrock-version-changer" aria-label="Permalink to &quot;Bedrock Version Changer {#bedrock-version-changer}&quot;">​</a></h3><p>Single pane: settings plus the recorded change history with a clear action.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>checkbox</td><td>on</td><td>Off hides the client tab and rejects installs.</td></tr><tr><td><code>allowed_types[]</code></td><td>checkboxes</td><td>both</td><td>Flavors users may install: Vanilla (official BDS) and PocketMine-MP.</td></tr><tr><td><code>allow_wipe</code></td><td>checkbox</td><td>on</td><td>Permit the wipe-before-install option.</td></tr><tr><td><code>allow_zip_wipe</code></td><td>checkbox</td><td>on</td><td>Permit archive-and-wipe (<code>backup-before-bedrock-&lt;timestamp&gt;.zip</code> left in the server root).</td></tr><tr><td><code>egg_ids</code></td><td>text</td><td>empty (every egg)</td><td>Restrict the picker to specific egg IDs.</td></tr><tr><td><code>cache_ttl</code></td><td>number (300–86400)</td><td><code>21600</code></td><td>Version catalogue cache lifetime.</td></tr><tr><td><code>history_limit</code></td><td>number (0–500)</td><td><code>50</code></td><td>Change records kept per server.</td></tr><tr><td><code>http_timeout</code> / <code>http_retries</code> <strong>(env-only)</strong></td><td>numbers</td><td><code>10</code> / <code>2</code> (<code>BEDROCK_VERSION_CHANGER_HTTP_TIMEOUT</code>, <code>…_HTTP_RETRIES</code>)</td><td>Catalogue request tuning.</td></tr></tbody></table><p><strong>Common mistakes:</strong> preview/beta builds are intentionally not offered — only stable releases; nodes must reach <code>www.minecraft.net</code> and <code>github.com</code> for the actual downloads.</p><hr><h3 id="database-manager" tabindex="-1">Database Manager <a class="header-anchor" href="#database-manager" aria-label="Permalink to &quot;Database Manager {#database-manager}&quot;">​</a></h3><p>Single settings pane plus a recent-operations log.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>max_export_mb</code></td><td>number</td><td><code>256</code></td><td>Databases estimated larger are refused before a dump starts.</td></tr><tr><td><code>max_import_mb</code></td><td>number</td><td><code>64</code></td><td>Upload cap for imports — the pane shows your live PHP <code>upload_max_filesize</code>/<code>post_max_size</code>; raise those first for large imports.</td></tr><tr><td><code>allow_export</code></td><td>checkbox</td><td>on</td><td>Users with <code>databasemanager.export</code> may download dumps.</td></tr><tr><td><code>allow_import</code></td><td>checkbox</td><td>on</td><td>Users with <code>databasemanager.import</code> may restore uploads.</td></tr><tr><td><code>allow_wipe</code></td><td>checkbox</td><td>on</td><td>Permit emptying the target schema before import.</td></tr><tr><td><code>log_activity</code></td><td>checkbox</td><td>on</td><td>Mirror each operation into the server&#39;s activity log.</td></tr><tr><td><code>mysqldump_binary</code> / <code>mysql_binary</code> / <code>work_directory</code> <strong>(env-only)</strong></td><td>—</td><td><code>mysqldump</code> / <code>mysql</code> / <code>storage/app/database-manager</code></td><td>Override via <code>DATABASE_MANAGER_MYSQLDUMP</code>, <code>DATABASE_MANAGER_MYSQL</code>, <code>DATABASE_MANAGER_WORKDIR</code>.</td></tr><tr><td><code>export_timeout</code> / <code>import_timeout</code> <strong>(env-only)</strong></td><td>seconds</td><td><code>280</code> / <code>580</code></td><td>Process limits.</td></tr></tbody></table><p><strong>Common mistakes:</strong> setting <code>max_import_mb</code> above the PHP upload limits; missing <code>default-mysql-client</code> on the panel host (both binaries must be reachable by the web user).</p><hr><h3 id="fastdl" tabindex="-1">FastDL Manager <a class="header-anchor" href="#fastdl" aria-label="Permalink to &quot;FastDL Manager {#fastdl}&quot;">​</a></h3><p>Single pane: navigation label, nest allow-list, the global default URL and per-node URL overrides.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>nav_label</code></td><td>text</td><td><code>FastDL</code></td><td>Client tab label.</td></tr><tr><td><code>allowed_nests</code></td><td>text</td><td>empty (every nest)</td><td>Comma-separated nest IDs the tab is available for.</td></tr><tr><td><code>default_url</code></td><td>url</td><td>empty</td><td>Global download base URL covering every node without its own override.</td></tr><tr><td><code>max_config_bytes</code> <strong>(env-only)</strong></td><td>number</td><td><code>1048576</code></td><td>Largest <code>server.cfg</code> the sync reads.</td></tr></tbody></table><p><strong>Managed data:</strong> per-node URL overrides (<code>node_id</code> + <code>url</code>). Built-in game profiles: Garry&#39;s Mod, CS:GO and CS 1.6 — the profile picks the URL subdirectory and the config path; the likely profile is preselected from the server&#39;s egg.</p><p><strong>Deliberately dropped:</strong> automatic web-server provisioning (nginx vhosts, TLS, file mirroring) — the competitor&#39;s version needs a node-side agent; this addon manages URLs and configs only, and its README ships a minimal vhost example.</p><p><strong>Common mistakes:</strong> the rule is base URL + game directory must reach the folder holding the server&#39;s <code>maps/</code>, <code>models/</code>, <code>sound/</code> and <code>materials/</code> folders — with a vhost rooted at the volumes directory the base URL ends in the server <code>&lt;uuid&gt;</code>; changes apply after a restart (Source games read <code>server.cfg</code> at boot).</p><hr><h3 id="fivem-utils" tabindex="-1">FiveM Utils <a class="header-anchor" href="#fivem-utils" aria-label="Permalink to &quot;FiveM Utils {#fivem-utils}&quot;">​</a></h3><p>Single pane: tab label, egg keywords, a review of which managed variables each matching egg defines, and a one-click variable re-sync for newly imported eggs.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>nav_label</code></td><td>text</td><td><code>FiveM Utils</code></td><td>Client tab label (<code>FIVEM_UTILS_NAV_LABEL</code>).</td></tr><tr><td><code>egg_keywords</code></td><td>text</td><td><code>fivem,txadmin,cfx</code></td><td>Egg-name keywords deciding where the page appears (<code>FIVEM_UTILS_EGG_KEYWORDS</code>).</td></tr><tr><td><code>artifact_cache_minutes</code> <strong>(env-only)</strong></td><td>number</td><td><code>360</code> (<code>FIVEM_UTILS_ARTIFACT_CACHE_MINUTES</code>)</td><td>Artifact feed cache lifetime (a static fallback ships).</td></tr></tbody></table><p><strong>Managed data:</strong> none — cards write the egg variables <code>GAME_BUILD</code>, <code>TXADMIN_ENABLE</code> / <code>TXADMIN_PORT</code>, <code>ARTIFACT_URL</code> and <code>MYSQL_CONNECTION_STRING</code>, which the installer adds to every matching egg automatically.</p><p><strong>Common mistakes:</strong> <code>ARTIFACT_URL</code> is consumed by the egg&#39;s install script on the next (re)install — a custom egg may need a one-line reference; the addon sets the txAdmin port variable but does not open firewall ports on the node.</p><hr><h3 id="github-source-control" tabindex="-1">Git Source Control <a class="header-anchor" href="#github-source-control" aria-label="Permalink to &quot;Git Source Control {#github-source-control}&quot;">​</a></h3><p>Single pane: host diagnostics (git version, volume root presence/writability, API base, linked-account count), settings, and the linked-account list with one-click revoke.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>nav_label</code></td><td>text (max 30)</td><td><code>Source Control</code></td><td>Client tab label.</td></tr><tr><td><code>allowed_nests</code></td><td>text</td><td>empty (every nest)</td><td>Comma-separated nest IDs the feature is available for.</td></tr><tr><td><code>allowed_hosts</code></td><td>text</td><td><code>github.com</code></td><td>Comma-separated HTTPS git hosts; tokens are only ever sent to these hosts.</td></tr><tr><td><code>allow_push</code></td><td>checkbox</td><td>on</td><td>Off panel-wide makes every mirror read-only.</td></tr><tr><td><code>allow_manual_url</code></td><td>checkbox</td><td>on</td><td>Permit cloning arbitrary HTTPS URLs on allowed hosts, not just the linked account&#39;s repository list.</td></tr><tr><td><code>volume_root</code> / <code>git_binary</code> / <code>command_timeout</code> / <code>api_base</code> <strong>(env-only)</strong></td><td>—</td><td><code>/var/lib/pterodactyl/volumes</code> / <code>git</code> / <code>120</code> s / <code>https://api.github.com</code></td><td><code>GSC_VOLUME_ROOT</code>, <code>GSC_GIT_BINARY</code>, <code>GSC_COMMAND_TIMEOUT</code>, <code>GSC_API_BASE</code> (point the last at a GitHub Enterprise Server, e.g. <code>https://git.example.com/api/v3</code>).</td></tr></tbody></table><p><strong>Managed data:</strong> linked connections (provider profile ↔ panel user); revoking forgets the stored token immediately.</p><p><strong>Common mistakes:</strong> servers whose volume is not mounted on the panel host (remote nodes without shared storage) show a clear &quot;files not reachable&quot; state — operations run panel-side against the volume root; pulls are fast-forward-only by design, so a diverged branch reports instead of merging.</p><hr><h3 id="hytale-mod-installer" tabindex="-1">Hytale Mod Installer <a class="header-anchor" href="#hytale-mod-installer" aria-label="Permalink to &quot;Hytale Mod Installer {#hytale-mod-installer}&quot;">​</a></h3><p>Single pane: the CurseForge API key.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>curseforge_api_key</code></td><td>text</td><td>empty</td><td>Required — CurseForge is currently the only public repository with a Hytale section.</td></tr><tr><td><code>install_directory</code> <strong>(env-only)</strong></td><td>path</td><td><code>/mods</code> (<code>HYTALE_MOD_INSTALLER_DIRECTORY</code>)</td><td>Server-relative install target.</td></tr><tr><td><code>http_timeout</code> / <code>cache_ttl</code> <strong>(env-only)</strong></td><td>seconds</td><td><code>15</code> / <code>900</code> (<code>HYTALE_MOD_INSTALLER_HTTP_TIMEOUT</code>, <code>…_CACHE_TTL</code>)</td><td>Catalogue request timeout and cache lifetime.</td></tr></tbody></table><p><strong>Common mistakes:</strong> non-Hytale eggs see an explanatory notice instead of the catalogue (the installed-mod list stays available); nodes must reach the CurseForge CDN for downloads.</p><hr><h3 id="hytale-world-manager" tabindex="-1">Hytale World Manager <a class="header-anchor" href="#hytale-world-manager" aria-label="Permalink to &quot;Hytale World Manager {#hytale-world-manager}&quot;">​</a></h3><p>Single pane: the CurseForge API key plus a panel-wide managed-world count.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>curseforge_api_key</code></td><td>text</td><td>empty</td><td>Required — the same key as the Hytale Mod Installer works.</td></tr><tr><td><code>worlds_directory</code> <strong>(env-only)</strong></td><td>path</td><td><code>/universe/worlds</code> (<code>HYTALE_WORLD_MANAGER_DIRECTORY</code>)</td><td>Where installed worlds land.</td></tr><tr><td><code>staging_directory</code> <strong>(env-only)</strong></td><td>path</td><td><code>/.hytale-world-manager</code> (<code>HYTALE_WORLD_MANAGER_STAGING</code>)</td><td>Hidden staging folder for unpacks.</td></tr><tr><td><code>http_timeout</code> / <code>cache_ttl</code> <strong>(env-only)</strong></td><td>seconds</td><td><code>15</code> / <code>900</code> (<code>HYTALE_WORLD_MANAGER_HTTP_TIMEOUT</code>, <code>…_CACHE_TTL</code>)</td><td>Catalogue request timeout and cache lifetime.</td></tr></tbody></table><p><strong>Common mistakes:</strong> activate worlds while the server is offline — Hytale rewrites its <code>config.json</code> while running, so activation always applies on the next start; the world the server currently loads cannot be removed.</p><hr><h3 id="mod-installer" tabindex="-1">Mod Installer <a class="header-anchor" href="#mod-installer" aria-label="Permalink to &quot;Mod Installer {#mod-installer}&quot;">​</a></h3><p>Single settings pane with provider status badges.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>curseforge_api_key</code></td><td>text</td><td>empty</td><td>From the CurseForge for Studios console. Modrinth needs no key; CurseForge stays hidden from users until a key is saved.</td></tr><tr><td><code>default_provider</code></td><td>select</td><td><code>modrinth</code></td><td>Preselected repository when a user opens the Mods page.</td></tr><tr><td><code>default_loader</code></td><td>select</td><td><code>fabric</code></td><td>Preselected loader filter (<code>fabric</code>/<code>forge</code>/<code>quilt</code>/<code>neoforge</code>/any); users can change it anytime.</td></tr><tr><td><code>install_directory</code> <strong>(env-only)</strong></td><td>path</td><td><code>/mods</code> (<code>MOD_INSTALLER_DIRECTORY</code>)</td><td>Server-relative install target.</td></tr><tr><td><code>http_timeout</code> / <code>version_manifest_ttl</code> <strong>(env-only)</strong></td><td>seconds</td><td><code>15</code> / <code>86400</code></td><td>Provider request timeout; Minecraft version manifest cache TTL.</td></tr><tr><td><code>search_cache_ttl</code> <strong>(env-only)</strong></td><td>seconds</td><td><code>300</code> (<code>MOD_INSTALLER_SEARCH_CACHE_TTL</code>)</td><td>Panel-side catalogue search/version-list cache.</td></tr><tr><td><code>job_timeout</code> <strong>(env-only)</strong></td><td>seconds</td><td><code>600</code> (<code>MOD_INSTALLER_JOB_TIMEOUT</code>)</td><td>Background download job limit.</td></tr><tr><td><code>analysis_limit</code> <strong>(env-only)</strong></td><td>bytes</td><td><code>26214400</code> (25 MB)</td><td>Largest jar read back for update detection.</td></tr></tbody></table><p><strong>Common mistakes:</strong> assuming CurseForge works without a key; blocking outbound HTTPS to <code>api.modrinth.com</code>, <code>api.curseforge.com</code> or <code>launchermeta.mojang.com</code> (panel) and the mod CDNs (nodes); CurseForge-installed jars reporting &quot;untracked&quot; in update checks — fingerprint matching is Modrinth-only.</p><hr><h3 id="modpack-installer" tabindex="-1">Modpack Installer <a class="header-anchor" href="#modpack-installer" aria-label="Permalink to &quot;Modpack Installer {#modpack-installer}&quot;">​</a></h3><p>Settings pane with health badges (zip extension, staging writable, per-platform status), usage counters and a recent-installs table, plus an <strong>Installs</strong> sub-tab (tasks running right now with phase/progress, and every pack currently tracked as installed panel-wide with its backup archive name).</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>enable_modrinth</code></td><td>checkbox</td><td>on</td><td>Modrinth works out of the box, no key required.</td></tr><tr><td><code>enable_curseforge</code></td><td>checkbox</td><td>off</td><td>Requires an API key from the CurseForge console.</td></tr><tr><td><code>curseforge_api_key</code></td><td>text</td><td>always rendered blank</td><td>Stored key is never shown; blank keeps it.</td></tr><tr><td><code>clear_curseforge_key</code></td><td>checkbox</td><td>off</td><td>Check + save to remove the stored key.</td></tr><tr><td><code>button_label</code></td><td>text (max 40)</td><td><code>Modpacks</code></td><td>File-manager button label.</td></tr><tr><td><code>results_per_page</code></td><td>number (5–50)</td><td><code>20</code></td><td>Search results per page.</td></tr><tr><td><code>cache_ttl_minutes</code></td><td>number (5–1440)</td><td><code>30</code></td><td>Platform response cache — respects catalogue rate limits.</td></tr><tr><td><code>max_archive_size_mb</code></td><td>number (10–2048)</td><td><code>512</code></td><td>Pack archives/bundles larger than this are rejected.</td></tr><tr><td><code>max_files_per_pack</code></td><td>number (10–20000)</td><td><code>2500</code></td><td>File-count cap per pack.</td></tr><tr><td><code>max_staged_file_mb</code> / <code>max_staged_total_mb</code></td><td>numbers</td><td><code>5</code> / <code>64</code></td><td>Caps for configs and other files shipped inside the pack archive.</td></tr><tr><td><code>plan_rate_limit</code> / <code>plan_rate_window</code></td><td>numbers</td><td><code>5</code> / <code>300</code></td><td>How often one user may prepare an install per server.</td></tr><tr><td><code>allow_clean_install</code></td><td>checkbox</td><td>on</td><td>Users may wipe the target directory before pack files land.</td></tr><tr><td><code>allow_zip_backup</code></td><td>checkbox</td><td>on</td><td>Users may pick <em>back up, wipe, then install</em> — current files are zipped into a <code>modpack-backup-&lt;date&gt;</code> archive left in the target directory first.</td></tr></tbody></table><p>Separate actions: <strong>Clear platform cache</strong>, <strong>Clear staging files</strong>, <strong>Reset defaults</strong> (resets limits, keeps the API key).</p><p><strong>Common mistakes:</strong> missing the PHP <code>zip</code> extension or a non-writable <code>storage/app/modpack-installer</code> (both shown as pane badges); expecting egg/Docker changes — the addon installs files only, and client-only mods plus third-party-opt-out files are auto-skipped and listed on the confirmation screen; uninstalling a pack installed before 1.1.0 — there is no file manifest, so the button explains why it cannot. A background install keeps its state in the panel cache for the plan lifetime (default 45 minutes); a cache flush mid-install settles the task as a clearly-labelled failure that can simply be started again.</p><hr><h3 id="node-stats" tabindex="-1">Node Stats <a class="header-anchor" href="#node-stats" aria-label="Permalink to &quot;Node Stats {#node-stats}&quot;">​</a></h3><p>Sub-tabs: <strong>Overview</strong>, <strong>Nodes</strong>, <strong>Capacity</strong>, <strong>Historical</strong>, <strong>Top Consumers</strong>, <strong>Reports</strong>, <strong>Settings</strong>.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>collection_enabled</code></td><td>yes/no radio</td><td>yes</td><td>Master switch for metric collection from Wings.</td></tr><tr><td><code>collection_interval</code></td><td>number (10–300)</td><td><code>30</code> s</td><td>How often metrics are collected.</td></tr><tr><td><code>retention_raw_days</code></td><td>number (1–365)</td><td><code>7</code></td><td>Raw snapshot retention.</td></tr><tr><td><code>retention_1m_days</code></td><td>number (1–365)</td><td><code>30</code></td><td>1-minute aggregate retention.</td></tr><tr><td><code>retention_5m_days</code></td><td>number (1–730)</td><td><code>90</code></td><td>5-minute aggregate retention.</td></tr><tr><td><code>retention_1h_days</code></td><td>number (1–1825)</td><td><code>365</code></td><td>Hourly aggregate retention.</td></tr><tr><td><code>retention_1d_days</code></td><td>number (1–3650)</td><td><code>1825</code></td><td>Daily aggregate retention.</td></tr><tr><td><code>retention.aggregates_1mo_days</code> <strong>(env-only)</strong></td><td>number</td><td><code>0</code> (keep forever)</td><td>Monthly aggregate retention.</td></tr></tbody></table><p><strong>Env-only (<code>config/nodeanalytics.php</code>):</strong> queue name <code>nodeanalytics</code>, batch sizes (collection 50 / aggregation 500), cache TTL 60 s, <code>reports.max_rows</code> 100000.</p><p><strong>Common mistakes:</strong> dashboards staying empty — the addon needs both the panel cron (the scheduler runs <code>nodeanalytics:schedule</code> every minute) <strong>and</strong> a Supervisor worker on the <code>nodeanalytics</code> queue (<code>data/install-queue-worker.sh</code> sets it up).</p><hr><h3 id="permission-manager" tabindex="-1">Permission Manager <a class="header-anchor" href="#permission-manager" aria-label="Permalink to &quot;Permission Manager {#permission-manager}&quot;">​</a></h3><p>Sub-tabs: <strong>Overview</strong>, <strong>Roles</strong>, <strong>Members</strong>, <strong>Audit Log</strong>. No global settings form — the panes manage roles, members and scoped assignments.</p><p><strong>Managed data:</strong></p><ul><li><strong>Roles</strong> — <code>name</code> (required), <code>description</code>, <code>pages[]</code> (which staff-area pages the role can open: Users, Servers, Nodes, Nests), <code>see_all_servers</code>, <code>see_all_users</code> (off = only explicitly assigned servers/users), <code>allow_build_edit</code> (edit CPU/memory/disk/swap/IO/feature limits via the panel&#39;s own build service), <code>subuser_permissions[]</code> (defaults to console, power actions and file read — provisioned as a <em>real</em> subuser on every in-scope server; editing re-syncs all members).</li><li><strong>Members</strong> — <code>user_id</code>, <code>role_id</code>, <code>active</code> (unchecking revokes access and provisioned subusers but keeps assignments). Per member: assign specific users (staff then see those users <em>and their servers</em>) and specific servers.</li><li><strong>Config-only (<code>config/permissionmanager.php</code>):</strong> the page list and <code>default_subuser_permissions</code> (<code>websocket.connect</code>, <code>control.console</code>, <code>control.start</code>, <code>control.stop</code>, <code>control.restart</code>, <code>file.read</code>, <code>file.read-content</code>).</li></ul><p><strong>Common mistakes:</strong> trying to delete a role that still has members (refused — reassign or remove them first); uninstalling without removing members or running <code>php artisan permgr:sync</code>, which leaves provisioned subusers behind.</p><hr><h3 id="player-list" tabindex="-1">Player List <a class="header-anchor" href="#player-list" aria-label="Permalink to &quot;Player List {#player-list}&quot;">​</a></h3><p>Single settings pane with a built-in host:port test tool (reports whether the full UDP query answered).</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>checkbox</td><td>on</td><td>Off hides the widget panel-wide without uninstalling.</td></tr><tr><td><code>protocol</code></td><td>select</td><td><code>auto</code></td><td><code>auto</code> (query, then ping), <code>query</code> (UDP query only), <code>ping</code> (status ping only). Query returns the full list but needs <code>enable-query=true</code>; ping needs no setup but returns only a name sample.</td></tr><tr><td><code>avatars</code></td><td>checkbox</td><td>on</td><td>Head images next to player names.</td></tr><tr><td><code>avatar_url</code> <strong>(env-only)</strong></td><td>url template</td><td><code>https://mc-heads.net/avatar/{name}/40</code> (<code>PLAYER_LIST_AVATAR_URL</code>)</td><td>Avatar provider; <code>{name}</code> placeholder. A local placeholder head is used when the image cannot be loaded.</td></tr><tr><td><code>actions</code></td><td>checkbox</td><td>on</td><td>Moderation menu on player rows (kick, ban, op/deop, gamemode, whitelist add/remove) for users with console access.</td></tr><tr><td><code>timeout_ms</code></td><td>number (250–10000)</td><td><code>2000</code></td><td>Per probe attempt.</td></tr><tr><td><code>cache_seconds</code></td><td>number (0–300)</td><td><code>15</code></td><td>Per-server result cache — prevents query floods.</td></tr><tr><td><code>poll_seconds</code></td><td>number (5–300)</td><td><code>20</code></td><td>Browser refresh interval of the console widget.</td></tr></tbody></table><p>All UI settings also have env defaults (<code>PLAYER_LIST_ENABLED</code>, <code>PLAYER_LIST_PROTOCOL</code>, <code>PLAYER_LIST_AVATARS</code>, <code>PLAYER_LIST_ACTIONS</code>, <code>PLAYER_LIST_TIMEOUT_MS</code>, <code>PLAYER_LIST_CACHE_SECONDS</code>, <code>PLAYER_LIST_POLL_SECONDS</code>).</p><p><strong>Common mistakes:</strong> expecting full player lists from servers without <code>enable-query=true</code> and the query port reachable from the panel — the ping fallback only ever returns a sample (the card&#39;s <strong>Enable query</strong> button writes <code>enable-query=true</code> and <code>query.port</code> for users with the file-edit permission; a restart is required); avatar images load client-side, so users&#39; browsers need outbound access to the avatar provider.</p><hr><h3 id="player-manager" tabindex="-1">Player Manager <a class="header-anchor" href="#player-manager" aria-label="Permalink to &quot;Player Manager {#player-manager}&quot;">​</a></h3><p>Single settings pane plus a stored-credentials table (passwords shown only as <code>stored</code>/<code>—</code>, never the value) with revocation.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>checkbox</td><td>on</td><td>Off answers the client page and every API action with a disabled notice.</td></tr><tr><td><code>avatars</code></td><td>checkbox</td><td>on</td><td>Head renders served through a caching panel-side proxy (browsers never contact third-party services).</td></tr><tr><td><code>playerdata</code></td><td>checkbox</td><td>on</td><td>Offline roster and the player-data viewer/editor (<code>playerdata/*.dat</code> via the node file API).</td></tr><tr><td><code>default_port</code></td><td>number (1–65535)</td><td><code>25575</code></td><td>Used when neither a stored override nor a server variable defines a port (vanilla default).</td></tr><tr><td><code>connect_timeout</code></td><td>number (1.0–15.0)</td><td><code>3.0</code> s</td><td>RCON connect timeout.</td></tr><tr><td><code>read_timeout</code></td><td>number (1.0–30.0)</td><td><code>4.0</code> s</td><td>RCON response timeout.</td></tr></tbody></table><p><strong>Config-only:</strong> the server-variable names consulted when no per-server override exists — <code>RCON_PASSWORD</code>, <code>RCON_PORT</code>, <code>RCON_HOST</code> (overridable via <code>PLAYER_MANAGER_VARIABLE_PASSWORD/PORT/HOST</code>).</p><p><strong>Common mistakes:</strong> servers unreachable because RCON is not enabled in <code>server.properties</code> — use the built-in <strong>Fix RCON</strong> button, which writes <code>enable-rcon=true</code>, <code>rcon.port</code> and <code>rcon.password</code> through the node&#39;s file API (generating and storing a password when the server has none); forgetting the credential resolution order — stored per-server override first, then server variables, host defaulting to the primary allocation; player-data edits/wipes are refused while the player is online.</p><hr><h3 id="plugin-installer" tabindex="-1">Plugin Installer <a class="header-anchor" href="#plugin-installer" aria-label="Permalink to &quot;Plugin Installer {#plugin-installer}&quot;">​</a></h3><p>Single settings pane (save only; no reset/test actions).</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>provider_modrinth</code> / <code>provider_hangar</code> / <code>provider_spiget</code></td><td>checkboxes</td><td>on</td><td>Free catalogues, no API key required. Spiget lists premium resources but cannot install them.</td></tr><tr><td><code>provider_curseforge</code></td><td>checkbox</td><td>off</td><td>Stays unavailable until a valid API key is saved, even when toggled on.</td></tr><tr><td><code>provider_polymart</code></td><td>checkbox</td><td>off</td><td>Marketplace catalogue; only entries flagged downloadable are installable.</td></tr><tr><td><code>curseforge_api_key</code></td><td>text</td><td>empty</td><td>From the CurseForge console; empty keeps CurseForge disabled.</td></tr><tr><td><code>install_directory</code></td><td>text</td><td><code>/plugins</code></td><td>Server-relative install target — <code>/plugins</code> for Bukkit-based, <code>/mods</code> for modded setups. Normalized to a leading slash; falls back to <code>/plugins</code> when empty, <code>/</code>, containing <code>..</code>, or over 64 chars.</td></tr><tr><td><code>analysis_max_mb</code></td><td>number (1–100)</td><td><code>15</code></td><td>Jars larger than this are listed in the Installed tab but skipped for metadata extraction and update checks.</td></tr><tr><td><code>provider_timeout</code> <strong>(env-only)</strong></td><td>seconds</td><td><code>20</code> (<code>PLUGIN_INSTALLER_PROVIDER_TIMEOUT</code>)</td><td>Catalogue request timeout.</td></tr><tr><td><code>catalogue_cache_ttl</code> <strong>(env-only)</strong></td><td>minutes</td><td><code>5</code> (<code>PLUGIN_INSTALLER_CACHE_TTL</code>)</td><td>Panel-side cache for search, version and details responses.</td></tr></tbody></table><p><strong>Common mistakes:</strong> no installs landing — nodes must reach the provider CDNs (Wings performs the download via native file-pull); strict CSP blocking provider icon hosts (icons fall back to letter placeholders).</p><hr><h3 id="reverse-proxy" tabindex="-1">Reverse Proxy <a class="header-anchor" href="#reverse-proxy" aria-label="Permalink to &quot;Reverse Proxy {#reverse-proxy}&quot;">​</a></h3><p>Sub-tabs: <strong>Settings</strong>, <strong>Whitelist</strong> (per-server limit overrides with a server search picker), <strong>All Proxies</strong> (every rule on the panel with server, owner, node, SSL and DNS status, plus delete for moderation).</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>allowed_nodes[]</code></td><td>checkboxes</td><td>empty (all nodes)</td><td>Restrict the feature to specific nodes.</td></tr><tr><td><code>default_proxy_limit</code></td><td>number (0–1000)</td><td><code>3</code></td><td>Proxy rules each server may create.</td></tr><tr><td><code>whitelist_enabled</code></td><td>checkbox</td><td>off</td><td>Whitelist mode gives individual servers their own limit.</td></tr></tbody></table><p><strong>Managed data:</strong> whitelist entries (<code>server</code>, <code>proxy_limit</code> 0–1000). Client rules carry <code>domain</code> (unique panel-wide), <code>allocation_id</code>, <code>ssl_type</code> (<code>none</code> / <code>letsencrypt</code> / <code>custom</code>) plus <code>ssl_email</code> or <code>ssl_certificate</code> + <code>ssl_key</code> — certificate material is write-only and never leaves the panel again.</p><p><strong>Deliberately dropped:</strong> automatic node-side provisioning — answering traffic for the domain needs a web server on the node, and the competitor&#39;s automation needs a node-side agent; this addon stores/validates the rules and renders a copy-paste nginx server block per rule instead.</p><p><strong>Common mistakes:</strong> a rule shows &quot;DNS pending&quot; until the domain&#39;s A record resolves to the node&#39;s public address; raw TCP/UDP game protocols are better served by SRV records (see <a href="#subdomain-manager">Subdomain Manager</a>) or an nginx <code>stream</code> block.</p><hr><h3 id="server-importer" tabindex="-1">Server Importer <a class="header-anchor" href="#server-importer" aria-label="Permalink to &quot;Server Importer {#server-importer}&quot;">​</a></h3><p>Sub-tabs: <strong>Overview</strong> (connections + runs) and <strong>Run report</strong>. No persistent settings — all inputs are per-operation.</p><p><strong>Managed data:</strong></p><ul><li><strong>Connections</strong> — <code>name</code>, <code>base_url</code> (public root URL of the source panel), <code>token</code> (Application API key <code>ptla_…</code>, min 16 chars, stored encrypted, with read access to servers, users, nodes, nests and eggs), <code>verify_tls</code> (on; uncheck for self-signed panels).</li><li><strong>Runs (dry run form)</strong> — <code>connection_id</code>, <code>target_node_id</code> (allocations claimed from its free pool), <code>fallback_egg_id</code> (optional; unmatched eggs otherwise become conflicts), <code>owner_strategy</code> (<code>map</code> by email / <code>fixed</code> one account), <code>fixed_user_id</code>, <code>create_missing_users</code>, <code>include_suspended</code>, <code>skip_scripts</code>.</li><li><strong>Config-only (<code>config/server-importer.php</code>):</strong> <code>per_page</code> 50, <code>timeout</code> 15 s, <code>connect_timeout</code> 8 s, <code>max_servers_per_run</code> 500.</li></ul><p><strong>Common mistakes:</strong> skipping the dry run — it builds the full conflict report and changes nothing; executing against a node without enough free allocations (claims are re-verified between dry run and import). Rollback force-deletes every server a run created.</p><hr><h3 id="server-properties" tabindex="-1">Server Properties <a class="header-anchor" href="#server-properties" aria-label="Permalink to &quot;Server Properties {#server-properties}&quot;">​</a></h3><p>Single settings pane.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>nav_label</code></td><td>text (max 30)</td><td><code>Properties</code></td><td>Label of the tab in the server sub-navigation.</td></tr><tr><td><code>file_name</code></td><td>text (max 64)</td><td><code>server.properties</code></td><td>File in the server root the editor reads/writes. Bare file names only.</td></tr><tr><td><code>allowed_nests</code></td><td>text</td><td><code>1</code></td><td>Comma-separated nest IDs the editor is available for (<code>1</code> = stock Minecraft). Empty = every nest.</td></tr><tr><td><code>show_descriptions</code></td><td>checkbox</td><td>on</td><td>Short explanation under each known key.</td></tr><tr><td><code>enable_motd</code></td><td>checkbox</td><td>on</td><td>MOTD editor (legacy <code>§</code> codes, MiniMessage, raw) with live server-list preview.</td></tr><tr><td><code>enable_icon</code></td><td>checkbox</td><td>on</td><td>Server icon manager — center-crop to exactly 64×64 PNG, verified again server-side.</td></tr><tr><td><code>enable_yaml</code></td><td>checkbox</td><td>on</td><td>Auto-detected YAML editor for root-level <code>.yml</code>/<code>.yaml</code> files, with BungeeCord-style proxy support and a raw mode.</td></tr><tr><td><code>max_file_bytes</code> <strong>(env-only)</strong></td><td>number</td><td><code>1048576</code> (<code>SERVERPROPERTIES_MAX_FILE_BYTES</code>)</td><td>Refuse to read files larger than this.</td></tr></tbody></table><p>The four original UI settings also have env defaults (<code>SERVERPROPERTIES_NAV_LABEL</code>, <code>SERVERPROPERTIES_FILE_NAME</code>, <code>SERVERPROPERTIES_ALLOWED_NESTS</code>, <code>SERVERPROPERTIES_SHOW_DESCRIPTIONS</code>).</p><p><strong>Common mistakes:</strong> expecting instant effect — Minecraft reads <code>server.properties</code>, <code>server-icon.png</code> and the YAML files at boot, so changes apply after a restart; the structured YAML editor rewrites the file from the parsed structure, so YAML comments are not preserved there (use raw mode for hand-tuned files); MiniMessage <code>&lt;rainbow&gt;</code> tags are not rendered in the MOTD preview and show literally.</p><hr><h3 id="server-splitter" tabindex="-1">Server Splitter <a class="header-anchor" href="#server-splitter" aria-label="Permalink to &quot;Server Splitter {#server-splitter}&quot;">​</a></h3><p>Sub-tabs: <strong>Overview</strong> (counters + policy summary), <strong>Whitelist</strong>, <strong>Splits</strong>, <strong>Link Servers</strong>, <strong>Settings</strong>.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>checkbox</td><td>on</td><td>Master switch for the client Splitter page.</td></tr><tr><td><code>allow_unlimited</code></td><td>checkbox</td><td>on</td><td>Unlimited masters (limit <code>0</code>) may hand out unlimited sub-servers.</td></tr><tr><td><code>whitelist_only</code></td><td>checkbox</td><td>off</td><td>Only whitelisted servers may split.</td></tr><tr><td><code>whitelist_fallback</code></td><td>checkbox</td><td>on</td><td>When a server has both a whitelist entry and matching rules, the higher allowance wins.</td></tr><tr><td><code>min_master_cpu</code> / <code>min_master_memory</code> / <code>min_master_disk</code></td><td>numbers</td><td><code>50</code> / <code>512</code> / <code>1024</code></td><td>Must remain on the master after a split (% / MB / MB).</td></tr><tr><td><code>min_sub_cpu</code> / <code>min_sub_memory</code> / <code>min_sub_disk</code></td><td>numbers</td><td><code>25</code> / <code>128</code> / <code>512</code></td><td>Every sub-server must receive at least this.</td></tr><tr><td><code>max_ports_per_sub</code> <strong>(env-only)</strong></td><td>number</td><td><code>10</code> (<code>SERVER_SPLITTER_MAX_PORTS</code>)</td><td>Port cap per sub-server.</td></tr><tr><td><code>sub_description</code> <strong>(env-only)</strong></td><td>text</td><td><code>Sub-server of {master}</code> (<code>SERVER_SPLITTER_SUB_DESCRIPTION</code>)</td><td>Description template for created sub-servers.</td></tr></tbody></table><p><strong>Managed data:</strong> whitelist entries (per-server fixed limits), resource-graded rules (&quot;at least 1 GB RAM may run 2 sub-servers&quot;) checked in an admin-defined <code>priority</code> order, and admin links (<code>master_server_id</code> ↔ <code>sub_server_id</code>) that attach an existing standalone server without moving resources.</p><p><strong>Common mistakes:</strong> a sub-server stuck in the <em>installing</em> state means the node was unreachable at creation — the bookkeeping is still correct, so reinstall it (or remove the split) once the node answers; after deleting sub-servers outside the splitter, run <code>php artisan server-splitter:reconcile</code> to credit the master back and clear stale markers.</p><hr><h3 id="server-type-changer" tabindex="-1">Server Type Changer <a class="header-anchor" href="#server-type-changer" aria-label="Permalink to &quot;Server Type Changer {#server-type-changer}&quot;">​</a></h3><p>Sub-tabs: <strong>Overview</strong> (settings + the last 25 change runs across all servers) and <strong>Whitelist</strong> (per-server grants by short identifier or UUID, with a name/identifier search helper).</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>checkbox</td><td>off</td><td>Master switch — the client page and API stay off until enabled.</td></tr><tr><td><code>allow_nest_changes</code></td><td>checkbox</td><td>on</td><td>Permit cross-nest moves.</td></tr><tr><td><code>allow_egg_changes</code></td><td>checkbox</td><td>on</td><td>Permit in-nest egg swaps.</td></tr><tr><td><code>blocked_nests[]</code> / <code>blocked_eggs[]</code></td><td>multi-selects</td><td>empty</td><td>Nests/eggs excluded from selection.</td></tr><tr><td><code>event_retention</code></td><td>number (1–200)</td><td><code>25</code></td><td>History entries kept per server.</td></tr></tbody></table><p><strong>Managed data:</strong> whitelist grants; without one the nav entry stays hidden and the API rejects requests (root admins and the <code>settings.reinstall</code> permission govern access).</p><p><strong>Common mistakes:</strong> a failed safety backup aborts the whole change before anything is touched — that is the point, check backup capacity instead of retrying blindly; suspended, installing, restoring or transferring servers are rejected until they settle; node-unreachable steps complete as <em>completed with warnings</em> naming the exact step that could not run.</p><hr><h3 id="staff-requests" tabindex="-1">Staff Requests <a class="header-anchor" href="#staff-requests" aria-label="Permalink to &quot;Staff Requests {#staff-requests}&quot;">​</a></h3><p>Single pane: policy settings, stat tiles, staff roster management, recent requests (with type + urgent badges and message previews), active grants, audit trail (the three tables are read-only; approve/deny/revoke happens on the user side).</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>access_mode</code></td><td>select</td><td><code>everyone</code></td><td>Who can use Staff Requests: <code>everyone</code>, <code>allowlist</code>, <code>blacklist</code>. Root admins always bypass.</td></tr><tr><td><code>allowlist</code></td><td>textarea</td><td>empty</td><td>One email per line; only these accounts may use the feature (shown when mode = allowlist).</td></tr><tr><td><code>blacklist</code></td><td>textarea</td><td>empty</td><td>One email per line; these accounts are blocked (shown when mode = blacklist).</td></tr><tr><td><code>request_decay_hours</code></td><td>number (1–8760)</td><td><code>24</code></td><td>Unanswered requests expire after this; runs on the panel&#39;s schedule cron.</td></tr><tr><td><code>block_rate_limit</code></td><td>number (1–1000)</td><td><code>10</code></td><td>Block-user actions per user per minute.</td></tr><tr><td><code>request_ttl_days</code> <strong>(env-only)</strong></td><td>number</td><td><code>14</code> (<code>ASKACCESS_REQUEST_TTL_DAYS</code>)</td><td>Separate backend validity window for pending requests — distinct from <code>request_decay_hours</code>.</td></tr><tr><td><code>max_pending_per_user</code> <strong>(env-only)</strong></td><td>number</td><td><code>25</code> (<code>ASKACCESS_MAX_PENDING</code>)</td><td>Pending-request cap per user.</td></tr><tr><td><code>create_rate_limit</code> / <code>create_rate_window_minutes</code> <strong>(env-only)</strong></td><td>numbers</td><td><code>15</code> / <code>60</code></td><td>Request-creation rate limit.</td></tr><tr><td><code>max_servers_per_grant</code> <strong>(env-only)</strong></td><td>number</td><td><code>250</code></td><td>Cap on servers touched by a single &quot;all servers&quot; approval.</td></tr></tbody></table><p><strong>Managed data (staff roster):</strong> <code>email</code> (required — the account is added by email, never enumerated) and an optional role <code>label</code> like &quot;Support&quot;. Roster members receive owner-initiated <strong>Request Staff Help</strong> requests; usernames are shown to users, emails are never exposed, and staff can still opt out via their own accept-requests toggle or blocks.</p><p><strong>Common mistakes:</strong> confused by the two expiry knobs (<code>request_decay_hours</code> in the UI vs <code>request_ttl_days</code> in env — both exist); expecting uninstall to clean up granted access — approved requests created <strong>real subuser rows</strong> that survive uninstall.</p><hr><h3 id="subdomain-manager" tabindex="-1">Subdomain Manager <a class="header-anchor" href="#subdomain-manager" aria-label="Permalink to &quot;Subdomain Manager {#subdomain-manager}&quot;">​</a></h3><p>Sub-tabs: <strong>Settings</strong>, <strong>Domains</strong>, <strong>Records</strong>, <strong>Limits</strong>.</p><p><strong>Settings tab</strong> (<code>admin.subdomainplus.settings</code>, plus <strong>Test Cloudflare connection</strong>):</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>cf_token</code></td><td>password</td><td>empty</td><td>Cloudflare API token with <strong>Zone / DNS / Edit</strong>. Placeholder shows &quot;(saved - enter to change)&quot; once set.</td></tr><tr><td><code>cf_email</code> / <code>cf_api_key</code></td><td>email / password</td><td>empty</td><td>Deprecated Global API Key mode — only use when a token is impossible.</td></tr><tr><td><code>default_quota</code></td><td>number (0–100)</td><td><code>5</code></td><td>DNS records per server; <code>0</code> = unlimited.</td></tr><tr><td><code>rate_per_minute</code></td><td>number (1–120)</td><td><code>5</code></td><td>Requests per minute per server.</td></tr></tbody></table><p><strong>Managed data (domains):</strong> <code>domain</code> and <code>zone_id</code> (required — or click <strong>Fetch zones from Cloudflare</strong> to pick from your account and auto-fill both), <code>allow_srv_record</code> / <code>allow_a_record</code> (both on), <code>allow_cname_record</code> (on; a requested A record becomes a CNAME when the allocation alias is a hostname — the <em>Use allocation IP</em> checkbox keeps the old behavior), <code>target_ip</code> (optional forced IP; empty auto-resolves from each server&#39;s allocation FQDN), SRV presets (<code>service</code> default <code>_minecraft</code>, <code>proto</code> <code>_tcp</code>/<code>_udp</code>, <code>priority</code> 0, <code>weight</code> 5, <code>ttl</code> 1 = automatic), <code>banned_patterns</code> (PHP regex, one per line), <code>allowed_eggs[]</code> (empty = all).</p><p><strong>Managed data (Limits tab):</strong> per-server quota overrides (<code>server_id</code> + <code>quota</code>) and the node policy — <code>node_policy</code> (allow or deny) with <code>node_ids[]</code>; restricted servers keep viewing/deleting existing records but cannot create new ones.</p><p><strong>Common mistakes:</strong> a token without Zone / DNS / Edit scope; expecting proxied records — the addon always creates unproxied records (SRV and CNAME require it); missing the panel cron, which drives <code>subdomainplus:sync-all</code> and orphan cleanup. The create form&#39;s live availability check blocks known-taken names before submit.</p><hr><h3 id="version-changer" tabindex="-1">Version Changer <a class="header-anchor" href="#version-changer" aria-label="Permalink to &quot;Version Changer {#version-changer}&quot;">​</a></h3><p>Settings pane plus a recent-changes table (saving settings also flushes the manifest cache), and a <strong>Server Access</strong> sub-tab for per-server grants (by short id or UUID).</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>checkbox</td><td>on</td><td>Off hides the picker in the client panel and rejects installs.</td></tr><tr><td><code>allowed_software[]</code></td><td>checkboxes</td><td>all</td><td>Software entries users may see: <code>vanilla</code>, <code>paper</code>, <code>purpur</code>, <code>folia</code>, <code>velocity</code>, <code>waterfall</code>.</td></tr><tr><td><code>allowed_types[]</code></td><td>checkboxes</td><td><code>release</code> only</td><td>Vanilla version types users may install: <code>release</code>, <code>snapshot</code>, <code>old_beta</code>, <code>old_alpha</code>.</td></tr><tr><td><code>allow_wipe</code></td><td>checkbox</td><td>on</td><td>Permit the archive-then-wipe and plain-wipe data options per install.</td></tr><tr><td><code>require_grant</code></td><td>checkbox</td><td>off</td><td>Restrict the feature to servers on the Server Access list.</td></tr><tr><td><code>default_filename</code></td><td>text</td><td><code>server.jar</code></td><td>Target jar name; must match a plain <code>.jar</code> file name (validated, resets to <code>server.jar</code> otherwise).</td></tr><tr><td><code>cache_ttl</code></td><td>number (60–86400)</td><td><code>300</code></td><td>Seconds the version/build catalogues are cached.</td></tr><tr><td><code>history_limit</code></td><td>number (0–500)</td><td><code>50</code></td><td>History entries kept per server, pruned after each install.</td></tr><tr><td><code>allow_filename_choice</code></td><td>checkbox</td><td>on</td><td>Let users override the jar name per install.</td></tr><tr><td><code>backup_previous</code></td><td>checkbox</td><td>on</td><td>Rename the current jar to <code>&lt;name&gt;.backup-&lt;timestamp&gt;</code> before writing (keep-files installs).</td></tr><tr><td><code>update_startup_variable</code></td><td>checkbox</td><td>on</td><td>Point the egg&#39;s <code>SERVER_JARFILE</code> variable at the new jar.</td></tr><tr><td><code>manifest_url</code> / <code>http_timeout</code> / <code>http_retries</code> <strong>(env-only)</strong></td><td>—</td><td>piston-meta URL / <code>10</code> / <code>2</code></td><td>Vanilla version-service endpoint and HTTP tuning (<code>VERSION_CHANGER_MANIFEST_URL</code>, <code>VERSION_CHANGER_HTTP_TIMEOUT</code>, <code>VERSION_CHANGER_HTTP_RETRIES</code>).</td></tr></tbody></table><p><strong>Common mistakes:</strong> assuming a mirror manifest widens download sources — jar downloads are pinned to the official hosts of each software (<code>mojang.com</code> / <code>minecraft.net</code>, <code>papermc.io</code>, <code>purpurmc.org</code>) regardless of the catalogue endpoints; expecting the running server to switch jars live — the old jar runs until the next restart.</p><hr><h3 id="votifier-tester" tabindex="-1">Votifier Tester <a class="header-anchor" href="#votifier-tester" aria-label="Permalink to &quot;Votifier Tester {#votifier-tester}&quot;">​</a></h3><p>Single pane: global toggle, default port and timeouts.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>checkbox</td><td>on</td><td>Off disables the client page and API panel-wide.</td></tr><tr><td><code>default_port</code></td><td>number (1–65535)</td><td><code>8192</code></td><td>Pre-filled listener port on the test form.</td></tr><tr><td><code>connect_timeout</code></td><td>number (1–15)</td><td><code>5.0</code> s</td><td>TCP connect timeout.</td></tr><tr><td><code>read_timeout</code></td><td>number (1–30)</td><td><code>5.0</code> s</td><td>Response timeout.</td></tr><tr><td><code>service_name</code> <strong>(env-only)</strong></td><td>text</td><td><code>VotifierTest</code> (<code>VOTIFIER_TESTER_SERVICE_NAME</code>)</td><td>Service name sent in test votes.</td></tr></tbody></table><p><strong>Common mistakes:</strong> the listener port must be reachable from the panel host (open the firewall / publish it for remote nodes); a well-formed vote is answered with silence — a clean handshake plus transmission counts as a pass, and the reward event shows up in the server console; tokens and public keys travel with the test only and are never persisted.</p><hr><h3 id="mc-world-manager" tabindex="-1">World Manager <a class="header-anchor" href="#mc-world-manager" aria-label="Permalink to &quot;World Manager {#mc-world-manager}&quot;">​</a></h3><p>Single settings pane.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>curseforge_api_key</code></td><td>text</td><td>empty</td><td>From the CurseForge console; the catalogue stays unavailable to users until one is saved.</td></tr><tr><td><code>default_sort</code></td><td>select</td><td><code>downloads</code></td><td>Preselected catalogue ordering.</td></tr><tr><td><code>nav_label</code></td><td>text (max 32)</td><td><code>Worlds</code></td><td>Client tab label.</td></tr><tr><td><code>catalog_ttl</code></td><td>number (60–86400)</td><td><code>900</code></td><td>Catalogue cache lifetime in seconds.</td></tr><tr><td><code>http_timeout</code> / <code>version_manifest_ttl</code> / <code>progress_ttl</code> <strong>(env-only)</strong></td><td>seconds</td><td><code>15</code> / <code>86400</code> / <code>600</code> (<code>MC_WORLD_MANAGER_HTTP_TIMEOUT</code>, <code>…_MANIFEST_TTL</code>, <code>…_PROGRESS_TTL</code>)</td><td>Request timeout, MC version manifest cache, install progress record lifetime.</td></tr></tbody></table><p><strong>Common mistakes:</strong> archives Wings cannot unpack (rar, 7z, plain gzip) are rejected with a clear message — repack as zip; switching the active world rewrites <code>level-name</code> in <code>server.properties</code>, so restart to play; manually uploaded worlds under a different directory name simply show without a catalogue badge.</p><hr><h2 id="what-s-next" tabindex="-1">What&#39;s Next? <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s Next?&quot;">​</a></h2><ul><li><strong><a href="./../user-guide/dashboard">The Hub Dashboard →</a></strong> — how panes, sub-tabs and saves work.</li><li><strong><a href="./../user-guide/addons">Addons Guide →</a></strong> — per-addon usage notes and client surfaces.</li></ul>',173))])}const f=a(i,[["render",l]]);export{b as __pageData,f as default};
